/**
 * Social-preview image, defined once.
 *
 * Both the build-time prerenderer (`vite.config.ts`) and the runtime head
 * (`lib/head.ts`) read these. They must agree: a crawler that does not run
 * JavaScript reads the prerendered tags, one that does reads whatever the app
 * sets afterwards, and if those differ the preview depends on which crawler
 * fetched it.
 *
 * The card itself is generated by `scripts/make-og-image.py`.
 */

import { SITE_URL } from "../data/profile";

export const OG_IMAGE_PATH = "/og-image.png";
export const OG_IMAGE_URL = `${SITE_URL}${OG_IMAGE_PATH}`;
export const OG_IMAGE_WIDTH = "1200";
export const OG_IMAGE_HEIGHT = "630";
export const OG_IMAGE_TYPE = "image/png";
export const OG_IMAGE_ALT =
  "Sinclair Nzenwata, software engineer and researcher. Building at the intersection of AI research and real-world engineering.";
export const TWITTER_HANDLE = "@nzenwata_";
